/**
 * Silent session close — no notices to customer or company.
 */
const { ChatSessions } = require('../../models');

async function closeSessionSilent(_whatsapp, session, opts = {}) {
  const closedBy = opts.closedBy || 'customer';
  if (!session?.id) return { ok: false, reason: 'no_session' };
  ChatSessions.close(session.id);
  console.log(
    `[SessionClose] #${session.id}[${session.session_code}] closed by ${closedBy} (silent)`
  );
  return { ok: true, notified: false };
}

module.exports = {
  closeSessionWithNotify: closeSessionSilent,
  closeSessionSilent,
  buildCustomerCloseNotice: () => '',
};
